// Create entries for each of the special folders.
for (const folderItem of specialFoldersMap) {
  const attributes = {
    label: folderItem.label,
    tooltiptext: `${folderItem.folderPath} – ${folderItem.serverName}`,
    crop: "start",
    ...this._getCssSelectorAttributes(folderItem.folder),
  };
  submenu.childWrapper.appendChild(
    this._buildMenuItem(attributes, folderItem.folder)
  );
}

if (specialFoldersMap.length === 0) {
  const stubItem = this._buildMenuItem(
    {
      "data-l10n-id":
        specialType === "recent"
          ? "menu-move-copy-no-recent"
          : "menu-move-copy-no-favorites",
      disabled: "true",
      "aria-disabled": "true",
    },
    null
  );
  stubItem.classList.add("stub-menuitem");
  submenu.childWrapper.appendChild(stubItem);
}

this._initializedSpecials.add(specialType);
